pub trait Policy<R> {
    fn decide(&self, sub: &Subject, act: Action, res: &R) -> Decision;
}
pub fn guard<R, T>(policy: &dyn Policy<R>, sub: &Subject, act: Action, res: &R,
                   op: impl FnOnce() -> T) -> Result<T, AccessDenied> {
    match policy.decide(sub, act, res) {          // deny by default
        Decision::Allow => Ok(op()),
        Decision::Deny(reason) => Err(AccessDenied { reason }),
    }
}

